///////////////////////////////////////////////////////////////////////////////////////////
// This sketch is a folk of saranomy's https://editor.p5js.org/saranomy/sketches/3PBgIF8UE
///////////////////////////////////////////////////////////////////////////////////////////
// Reference: Particle Life - A Game of Life Made of Particles
// https://www.youtube.com/watch?v=Z_zmZ23grXE&t=55s
///////////////////////////////////////////////////////////////////////////////////////////
class Particle {
  constructor(type, x, y) {
    this.type = type
    this.x = x
    this.y = y
    this.vx = 0
    this.vy = 0
    this.r = 3
    this.slow = 0.9
    this.rmax = 30 + type * 15
    this.rmin=this.rmax/4
  }
  draw() {
    fill(['red', 'green', 'blue'][this.type])
    ellipse(this.x, this.y, this.r * 2)
  }
  update() {
    for (const other of particles) {
      if (this === other) continue;
      const dx = other.x - this.x
      const dy = other.y - this.y
// The dist function in p5js is very laggy
      const d = sqrt(dx ** 2 + dy ** 2)

      if (d < this.rmin) {
        const k = 1/(d+2)-1/(this.rmin+2)
        this.vx -= k * dx
        this.vy -= k * dy
      } else if (d < this.rmax) {
// Red likes blue, green likes red, blue likes green
        if ((3 + this.type - other.type) % 3 == 2) {
          const k = .015
          this.vx += k * dx
          this.vy += k * dy
// Any types hate their own kind
        } else if (this.type == other.type) {
          const k = .01
          this.vx -= k * dx
          this.vy -= k * dy
        }
      }
    }
    const v = createVector(this.vx, this.vy).limit(4)
    this.vx = v.x
    this.vy = v.y
    this.x += this.vx
    this.y += this.vy
    this.vx *= this.slow
    this.vy *= this.slow
    this.x = (this.x + width) % width
    this.y = (this.y + height) % height
  }
}
////////////////////////////////////////////////////////////////////////////////////////////////////
let lastTime = Date.now()
let sum = 0
let fps = 0
let particles = []
////////////////////////////////////////////////////////////////////////////////////////////////////
setup = () => {
  createCanvas(640, 640)
  noStroke()
  for (let i = 350; i--;) {
    spawn()
  }
}
spawn = () => {
  let r = random()
  let type = int(random(3))
  let x = random(0, width)
  let y = random(0, height)
  particles.push(new Particle(type, x, y))
}
draw = () => {
  background(255)
  for (const p of particles) {
    p.update()
    p.draw()
  }
  fill('black')
  sum += Date.now() - lastTime
  if (frameCount % 5 == 0) {
    fps = 1000 / (sum / 5)
    sum = 0
  }
  text(floor(fps) + "fps", 5, 10)
  lastTime = Date.now()
}
